# Event: 20261026_gitin2316-sml-spikes-webservice (GITIN-2316)
# C3b - SOLO LECTURA, en SFCG-WEBS-01. Una sola linea de canalizacion (evita problemas al pegar varias lineas en la consola).
#       Lee el log del dia del sitio (Get-Content abre con lectura compartida, IIS lo tiene abierto), toma las lineas de la IP 181.116.88.166,
#       las separa con los nombres de #Fields y muestra: total, primera y ultima hora (UTC), metodo+estado, y todas las lineas que NO son 404 (hora, metodo, ruta sin query, estado).
"HOST: $env:COMPUTERNAME"; $f='D:\SmartFran\inetpub\W3SVC2\u_ex261027.log'; $h=((Get-Content $f -TotalCount 10 | Where-Object { $_ -like '#Fields:*' } | Select-Object -First 1).Substring(9)).Split(' '); $r=@(Get-Content $f | Where-Object { $_ -and $_[0] -ne '#' -and $_.Contains(' 181.116.88.166 ') } | ConvertFrom-Csv -Delimiter ' ' -Header $h); "Total desde esa IP: $($r.Count)"; if ($r.Count) { "Primero/ultimo (UTC): $($r[0].time) / $($r[-1].time)" }; "`n== metodo y estado"; $r | Group-Object 'cs-method','sc-status' | Sort-Object Count -Descending | ForEach-Object { "$($_.Name)`t$($_.Count)" }; "`n== no 404 (hora, metodo, ruta, estado)"; $r | Where-Object { $_.'sc-status' -ne '404' } | ForEach-Object { "$($_.time)`t$($_.'cs-method')`t$($_.'cs-uri-stem')`t$($_.'sc-status')" }
